#!/bin/sh
# Name: WeRead for Kindle
# Icon: data:image/png;base64,
# WeReadCatalogAccess: deferred-v1
set -eu
umask 077
WEREAD_HOME=${WEREAD_HOME:-/mnt/us/weread}
export WEREAD_HOME

# Explicit diagnostic arguments retain the supervisor's existing behavior.
# Ordinary Library activation waits for its independent recovery worker.
if [ "$#" -eq 0 ]; then set -- --library; fi
exec sh "$WEREAD_HOME/launch.sh" "$@"
